	static class CounterBackgroundCellRenderer : AbstractGColumnRenderer<string> {
		Color foregroundColor = getForeground();

		protected int measureColWidth(string sample) {
			Font font = getFont();
			Insets insets = getBorder().getBorderInsets(this);
			return (int) font.getStringBounds(sample, METRIC_FRC).getWidth() + insets.left +
				insets.right;
		}

		protected int measureWidthHtml(string sampleHtml) {
			string sampleText = HTMLUtilities.fromHTML(sampleHtml);
			return measureColWidth(sampleText);
		}

		/* @Override */
		public Component getTableCellRendererComponent(GTableCellRenderingData data) {
			base.getTableCellRendererComponent(data);
			JTable table = data.getTable();
			setForeground(table.getForeground());
			PcodeRow row = (PcodeRow) data.getRowObject();
			if (data.isSelected()) {
				if (row.isNext()) {
					Color blend =
						ColorUtils.blend(COLOR_BACKGROUND_COUNTER, COLOR_BACKGROUND_CURSOR, 0.5f);
					if (blend != null) {
						setBackground(blend);
					}
				}
				// else background is already set. Leave it alone
			}
			else if (row.isNext()) {
				setBackground(COLOR_BACKGROUND_COUNTER);
			}
			else {
				setBackground(table.getBackground());
				setOpaque(true);
			}
			setBorder(noFocusBorder);
			return this;
		}

		/* @Override */
		public string getFilterString(string t, Settings settings) {
			return t;
		}
	}

